class Entity {
  constructor(...components) { this.components = components; }
  update(dt) {
    for (const c of this.components) c.update?.(this, dt);
  }
}

const bjorn = new Entity(
  { update: (e, dt) => applyInput(e, dt) },   // input capability
  physicsComponent,
  graphicsComponent,
);
